version.transform:
(
  $Locations := [$uniq(Locations)];

  $locations := $query(
    {
      "statement":'query getLocations($where:LocationWhereInput!){
        location(where: $where){
          edges {
            node {
              id
              name
            }
          }
        }
      }',
      "variables":{
        "where": {
          "name": {
            "_in": [$Locations]
          }
        }
      }
    }
  ).location.edges.node;

  $locations.{
    name:id
  };
)
